cd /tmp/sv-13afeb57340a42258e6a2fa9572a4cb0/advanced-multi-complexity && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for f in p['frameworks']:
            for pkg in f['topLevelPackages']:
                key = (name, f['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    proj, fw, pkg = key
    bv = b.get(key)
    av = a.get(key)
    if bv and av and bv == av:
        unchanged.append((proj, fw, pkg, av))
    elif bv and av and bv != av:
        changes.append((proj, fw, pkg, bv, av, 'Aligned to highest version'))
    elif bv and not av:
        changes.append((proj, fw, pkg, bv, '-', 'Removed'))
    elif not bv and av:
        changes.append((proj, fw, pkg, '-', av, 'Added'))

print('=== CHANGES ===')
for c in changes:
    print(f'{c[0]:20s} {c[1]:10s} {c[2]:50s} {c[3]:10s} -> {c[4]:10s} ({c[5]})')
print()
print(f'=== UNCHANGED ({len(unchanged)} packages) ===')
for u in unchanged:
    print(f'{u[0]:20s} {u[1]:10s} {u[2]:50s} {u[3]}')
"

